.chat-copilot {
  position: sticky;
  top: 16px;
}

.chat-log {
  height: 480px;
  overflow-y: auto;
  padding: 12px;
  border: 1px solid var(--studio-border);
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.4);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.chat-bubble {
  max-width: 92%;
  padding: 10px 12px;
  border-radius: 10px;
  font-size: 0.88rem;
  line-height: 1.45;
  white-space: pre-wrap;
  word-break: break-word;
}

.chat-bubble--user {
  align-self: flex-end;
  background: rgba(99, 102, 241, 0.22);
  border: 1px solid rgba(99, 102, 241, 0.35);
}

.chat-bubble--assistant {
  align-self: flex-start;
  background: var(--studio-surface-strong);
  border: 1px solid var(--studio-border);
}

.chat-bubble--tool {
  align-self: flex-start;
  background: rgba(245, 158, 11, 0.12);
  border: 1px solid rgba(245, 158, 11, 0.3);
  font-size: 0.8rem;
  color: var(--studio-amber);
}

.chat-input-row {
  display: flex;
  gap: 8px;
  margin-top: 10px;
}

.chat-quick-pills {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-bottom: 12px;
}

.thinking {
  display: inline-flex;
  gap: 4px;
  align-items: center;
  color: var(--studio-muted);
  font-size: 0.82rem;
}

/* ------------------------------------------------------------------ */
/* Toasts                                                             */
/* ------------------------------------------------------------------ */
.toast-stack {
  position: fixed;
  right: 20px;
  bottom: 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  z-index: 1000;
  max-width: 360px;
}

.toast {
  padding: 10px 14px;
  border-radius: 8px;
  font-size: 0.85rem;
  background: rgba(15, 23, 42, 0.95);
  border: 1px solid var(--studio-border);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

.toast--success {
  border-color: rgba(16, 185, 129, 0.5);
  color: var(--studio-green);
}

.toast--error {
  border-color: rgba(239, 68, 68, 0.5);
  color: var(--studio-red);
}

.toast--info {
  border-color: rgba(99, 102, 241, 0.5);
  color: var(--studio-indigo);
}

/* ------------------------------------------------------------------ */
/* Settings drawer + badges                                           */
/* ------------------------------------------------------------------ */
.settings-drawer {
  background: var(--studio-surface);
  border: 1px solid var(--studio-border);
  border-radius: 10px;
  padding: 14px 16px;
  margin-bottom: 16px;
}

.source-badge {
  font-size: 0.75rem;
  color: var(--studio-muted);
  margin-left: 8px;
}

.cached-badge {
  color: var(--studio-amber);
}

a {
  color: var(--studio-indigo);
}

:focus-visible {
  outline: 2px solid var(--studio-indigo);
  outline-offset: 2px;
}

